// === GENERADOR DE HORARIOS DISPONIBLES POR DOCTOR ===

// 1. Eventos ocupados del calendario
const eventos = $items('Obtener eventos próximos 10 días');
const ocupadosPorDia = {};

console.log('=== DEBUG: Total eventos recibidos:', eventos.length);

eventos.forEach(item => {
  const ev = item.json;
  console.log('Evento:', JSON.stringify(ev, null, 2));

  if (ev.start && ev.start.dateTime) {
    const start = new Date(ev.start.dateTime);
    const end = ev.end && ev.end.dateTime ? new Date(ev.end.dateTime) : start;

    const fecha = start.toISOString().split('T')[0];
    const horaInicio = start.toTimeString().substring(0, 5); // HH:MM
    const horaFin = end.toTimeString().substring(0, 5);

    console.log(`  → Fecha: ${fecha}, Hora: ${horaInicio} - ${horaFin}`);

    if (!ocupadosPorDia[fecha]) ocupadosPorDia[fecha] = [];

    // Marcar todas las horas ocupadas entre inicio y fin
    let actual = new Date(start);
    while (actual < end) {
      const h = actual.toTimeString().substring(0, 5);
      if (!ocupadosPorDia[fecha].includes(h)) {
        ocupadosPorDia[fecha].push(h);
      }
      actual.setMinutes(actual.getMinutes() + 60); // cada hora
    }
  }
});

console.log('Horas ocupadas por día:', JSON.stringify(ocupadosPorDia, null, 2));

// 2. Datos del doctor elegido
const doctor = $items('Obtener doctores1')[0]?.json;
if (!doctor) {
  throw new Error('No se encontró el doctor seleccionado');
}

console.log('Doctor seleccionado:', doctor.nombre, 'Calendar ID:', doctor.calendar_id);

// horario_inicio / horario_fin
const horaInicio = doctor.horario_inicio.substring(0,5);
const horaFin    = doctor.horario_fin.substring(0,5);

// dias_trabajo
const diasTrabajo = doctor.dias_trabajo || [];
console.log('Días de trabajo:', diasTrabajo);

// Mapa de número de día a nombre
const mapaDias = {
  0: 'domingo',
  1: 'lunes',
  2: 'martes',
  3: 'miércoles',
  4: 'jueves',
  5: 'viernes',
  6: 'sábado',
};

// Helper: generar horas
function generarHoras(horaInicio, horaFin, pasoMin = 60) {
  const horas = [];
  const [hIni, mIni] = horaInicio.split(':').map(Number);
  const [hFin, mFin] = horaFin.split(':').map(Number);

  let actual = new Date(2000, 0, 1, hIni, mIni);
  const fin  = new Date(2000, 0, 1, hFin, mFin);

  while (actual < fin) {
    const hh = String(actual.getHours()).padStart(2, '0');
    const mm = String(actual.getMinutes()).padStart(2, '0');
    horas.push(`${hh}:${mm}`);
    actual.setMinutes(actual.getMinutes() + pasoMin);
  }
  return horas;
}

const horasDia = generarHoras(horaInicio, horaFin, doctor.duracion || 60);
console.log('Horas diarias posibles:', horasDia);

// 3. Generar slots
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

const horarios = [];
const diasBuscados = 3;
let diasEncontrados = 0;
let d = 0;

while (diasEncontrados < diasBuscados && d < 14) {
  const fecha = new Date(hoy);
  fecha.setDate(fecha.getDate() + d);
  d++;

  const diaNum = fecha.getDay();
  const diaNom = mapaDias[diaNum];

  if (!diasTrabajo.includes(diaNom)) continue;

  const fechaStr = fecha.toISOString().split('T')[0];
  const ocupadas = ocupadosPorDia[fechaStr] || [];

  console.log(`Día ${fechaStr} (${diaNom}): ocupadas = [${ocupadas.join(', ')}]`);

  for (const hora of horasDia) {
    if (ocupadas.includes(hora)) {
      console.log(`  × ${hora} ocupada`);
      continue;
    }

    console.log(`  ✓ ${hora} disponible`);
    horarios.push({
      fecha: fechaStr,
      hora,
      doctor_nombre: doctor.nombre,
      doctor_id: doctor.id,
      especialidad: doctor.especialidad,
    });
  }

  diasEncontrados++;
}

console.log('Total horarios generados:', horarios.length);

return [{ json: { horarios } }];

// === GENERADOR DE HORARIOS DISPONIBLES POR DOCTOR ===

// 1. Eventos ocupados del calendario
const eventos = $items('Obtener eventos próximos 10 días');
const ocupadosPorDia = {};

eventos.forEach(item => {
  const ev = item.json;
  if (ev.start && ev.start.dateTime) {
    const start = new Date(ev.start.dateTime);
    const fecha = start.toISOString().split('T')[0];
    const hora = start.toTimeString().substring(0, 5); // HH:MM

    if (!ocupadosPorDia[fecha]) ocupadosPorDia[fecha] = [];
    ocupadosPorDia[fecha].push(hora);
  }
});

// 2. Datos del doctor elegido
const doctor = $items('Obtener doctores1')[0]?.json;
if (!doctor) {
  throw new Error('No se encontró el doctor seleccionado');
}

// horario_inicio / horario_fin por ejemplo "08:00:00"
const horaInicio = doctor.horario_inicio.substring(0,5); // "08:00"
const horaFin    = doctor.horario_fin.substring(0,5);    // "17:00"

// dias_trabajo es un array JSON de strings: ["lunes","martes",...]
const diasTrabajo = doctor.dias_trabajo || [];

// Mapa de número de día a nombre
const mapaDias = {
  0: 'domingo',
  1: 'lunes',
  2: 'martes',
  3: 'miércoles',
  4: 'jueves',
  5: 'viernes',
  6: 'sábado',
};

// Helper: generar horas entre inicio y fin cada 60 min
function generarHoras(horaInicio, horaFin, pasoMin = 60) {
  const horas = [];
  const [hIni, mIni] = horaInicio.split(':').map(Number);
  const [hFin, mFin] = horaFin.split(':').map(Number);

  let actual = new Date(2000, 0, 1, hIni, mIni);
  const fin  = new Date(2000, 0, 1, hFin, mFin);

  while (actual < fin) {
    const hh = String(actual.getHours()).padStart(2, '0');
    const mm = String(actual.getMinutes()).padStart(2, '0');
    horas.push(`${hh}:${mm}`);
    actual.setMinutes(actual.getMinutes() + pasoMin);
  }
  return horas;
}

const horasDia = generarHoras(horaInicio, horaFin, doctor.duracion || 60);

// 3. Generar slots por los próximos 10 días para ESTE doctor
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

const horarios = [];
const maxHorarios = 6;        // máximo total a devolver
const maxPorDia   = 2;        // máximo por día
const usadosPorDia = {};

for (let d = 0; d < 10; d++) {
  const fecha = new Date(hoy);
  fecha.setDate(fecha.getDate() + d);

  const diaNum = fecha.getDay();            // 0=Dom
  const diaNom = mapaDias[diaNum];

  // Saltar si el doctor no trabaja ese día
  if (!diasTrabajo.includes(diaNom)) continue;

  const fechaStr = fecha.toISOString().split('T')[0];
  const ocupadas = ocupadosPorDia[fechaStr] || [];

  if (!usadosPorDia[fechaStr]) usadosPorDia[fechaStr] = 0;

  for (const hora of horasDia) {
    if (ocupadas.includes(hora)) continue;             // hora ocupada en calendar
    if (usadosPorDia[fechaStr] >= maxPorDia) break;    // ya hay suficientes en ese día

    horarios.push({
      fecha: fechaStr,
      hora,
      doctor_nombre: doctor.nombre,
      doctor_id: doctor.id,
      especialidad: doctor.especialidad,
    });

    usadosPorDia[fechaStr] += 1;

    if (horarios.length >= maxHorarios) break;
  }

  if (horarios.length >= maxHorarios) break;
}

// Log para debug
console.log('horarios generados:', horarios);

return [{ json: { horarios } }];
